0155 | function findOptionalParentheticalGroups(value: string): ParentheticalGroup[] {
0156 |   const groups: ParentheticalGroup[] = [];
0157 |   let index = 0;
0158 | 
0159 |   while (index < value.length) {
0160 |     if (value[index] !== '(') {
0161 |       index += 1;
0162 |       continue;
0163 |     }
0164 | 
0165 |     const start = index;
0166 |     let depth = 1;
0167 |     index += 1;
0168 |     while (index < value.length && depth > 0) {
0169 |       if (value[index] === '(') depth += 1;
0170 |       if (value[index] === ')') depth -= 1;
0171 |       index += 1;
0172 |     }
0173 | 
0174 |     if (depth !== 0) break;
0175 |     const end = index;
0176 |     if (value.slice(start + 1, end - 1).length > 0) {
0177 |       groups.push({ start, end });
0178 |     }
0179 |   }
0180 | 
0181 |   return groups;
0182 | }
