0198 |     let after = result.slice(group.end);
0199 | 
0200 |     if (before.endsWith(' ') && (after.length === 0 || after.startsWith(' '))) {
0201 |       before = before.slice(0, -1);
0202 |     } else if (before.endsWith(' ') && startsWithTightPunctuation(after)) {
0203 |       before = before.slice(0, -1);
0204 |     } else if (before.length === 0 && after.startsWith(' ')) {
0205 |       after = after.slice(1);
0206 |     }
0207 | 
0208 |     result = before + after;
0209 |   }
0210 |   return result;
